mapper.select:
SELECT s.id AS sentence_id, s.bank_id AS bank_id, s.version AS version, s.current_version_id AS version_id, v.version_no AS version_no, s.status AS status, v.zh AS zh, v.ref AS ref, v.note AS note, v.chunks AS chunks, v.blank AS blank, v.tags AS tags, v.level AS level FROM sentences s JOIN sentence_banks b ON b.id = s.bank_id JOIN sentence_versions v ON v.id = s.current_version_id WHERE b.status = 'PUBLISHED' AND b.deleted_at IS NULL AND s.status = 'PUBLISHED' AND s.deleted_at IS NULL
AND s.bank_id = #{bankId}
AND s.id != #{excludeSentenceId}
ORDER BY s.created_at ASC, s.id ASC LIMIT #{limit}
